/**
 * HDR 支援插件
 *
 * 偵測視頻的 HDR 資訊並提供 HDR 模式切換功能
 */

import type { MpvPlugin, PluginInstance } from '../../core/types/plugin';
import type { MpvVideoElement } from '../../renderer/ui/MpvVideoElement';

/**
 * HDR 資訊
 */
export interface HdrInfo {
    /** 色彩原色（如 bt.2020） */
    primaries: string;
    /** 傳輸特性/gamma（如 pq, hlg） */
    gamma: string;
    /** 信號峰值亮度 */
    sigPeak: number;
    /** 是否為 HDR 內容 */
    isHdr: boolean;
}

/**
 * HDR 插件配置
 */
export interface HdrPluginOptions {
    /** 是否自動偵測並啟用 HDR */
    autoEnable?: boolean;
    /** HDR 模式變更回調 */
    onHdrChange?: (info: HdrInfo) => void;
}

/**
 * HDR 插件定義
 */
export const HdrPlugin: MpvPlugin<HdrPluginOptions> = {
    name: 'hdr',
    version: '1.0.0',

    install(player, options = {}) {
        return new HdrManager(player, {
            autoEnable: options.autoEnable ?? true,
            onHdrChange: options.onHdrChange,
        });
    },
};

/**
 * HDR 管理器
 */
export class HdrManager implements PluginInstance {
    readonly name = 'hdr';

    private player: MpvVideoElement;
    private options: Required<Omit<HdrPluginOptions, 'onHdrChange'>> & Pick<HdrPluginOptions, 'onHdrChange'>;

    // 狀態
    private _hdrInfo: HdrInfo = {
        primaries: '',
        gamma: '',
        sigPeak: 1,
        isHdr: false,
    };
    private _hdrModeEnabled: boolean = false;
    private _enabled: boolean = true;

    // 事件處理器
    private loadedmetadataHandler: (() => void) | null = null;

    constructor(player: MpvVideoElement, options: Required<Omit<HdrPluginOptions, 'onHdrChange'>> & Pick<HdrPluginOptions, 'onHdrChange'>) {
        this.player = player;
        this.options = options;

        this.initialize();
    }

    private initialize(): void {
        // 監聯媒體載入事件
        this.loadedmetadataHandler = () => {
            if (!this._enabled) return;
            this.detectHdr();
        };

        this.player.addEventListener('loadedmetadata', this.loadedmetadataHandler);

        // 如果已經載入，立即偵測
        if (this.player.readyState >= 1) {
            this.detectHdr();
        }
    }

    private async detectHdr(): Promise<void> {
        // 調用播放器的 HDR API
        const playerAny = this.player as unknown as {
            getHdrInfo?(): Promise<HdrInfo>;
            setHdrMode?(enabled: boolean): Promise<void>;
        };

        if (typeof playerAny.getHdrInfo !== 'function') {
            return;
        }

        try {
            const info = await playerAny.getHdrInfo();
            this._hdrInfo = {
                ...info,
                isHdr: this.checkIsHdrContent(info),
            };

            // 觸發回調
            this.options.onHdrChange?.(this._hdrInfo);

            // 自動啟用 HDR 模式
            if (this.options.autoEnable && this._hdrInfo.isHdr) {
                await this.enableHdrMode();
            }
        } catch (error) {
            console.error('[HdrPlugin] Failed to detect HDR:', error);
        }
    }

    private checkIsHdrContent(info: HdrInfo): boolean {
        // 判斷是否為 HDR 內容
        const hdrPrimaries = ['bt.2020', 'display-p3'];
        const hdrGamma = ['pq', 'hlg', 'smpte-st2084'];

        const hasBtPrimaries = hdrPrimaries.some(p =>
            info.primaries.toLowerCase().includes(p.toLowerCase())
        );
        const hasHdrGamma = hdrGamma.some(g =>
            info.gamma.toLowerCase().includes(g.toLowerCase())
        );

        return hasBtPrimaries || hasHdrGamma || info.sigPeak > 1;
    }

    // ===== 公開 API =====

    /** 獲取當前 HDR 資訊 */
    get hdrInfo(): HdrInfo {
        return { ...this._hdrInfo };
    }

    /** 是否為 HDR 內容 */
    get isHdrContent(): boolean {
        return this._hdrInfo.isHdr;
    }

    /** HDR 模式是否已啟用 */
    get hdrModeEnabled(): boolean {
        return this._hdrModeEnabled;
    }

    /** 啟用 HDR 模式 */
    async enableHdrMode(): Promise<void> {
        const playerAny = this.player as unknown as {
            setHdrMode?(enabled: boolean): Promise<void>;
        };

        if (typeof playerAny.setHdrMode !== 'function') {
            console.warn('[HdrPlugin] setHdrMode not available');
            return;
        }

        try {
            await playerAny.setHdrMode(true);
            this._hdrModeEnabled = true;
        } catch (error) {
            console.error('[HdrPlugin] Failed to enable HDR mode:', error);
        }
    }

    /** 停用 HDR 模式 */
    async disableHdrMode(): Promise<void> {
        const playerAny = this.player as unknown as {
            setHdrMode?(enabled: boolean): Promise<void>;
        };

        if (typeof playerAny.setHdrMode !== 'function') {
            return;
        }

        try {
            await playerAny.setHdrMode(false);
            this._hdrModeEnabled = false;
        } catch (error) {
            console.error('[HdrPlugin] Failed to disable HDR mode:', error);
        }
    }

    /** 切換 HDR 模式 */
    async toggleHdrMode(): Promise<void> {
        if (this._hdrModeEnabled) {
            await this.disableHdrMode();
        } else {
            await this.enableHdrMode();
        }
    }

    /** 重新偵測 HDR */
    async refresh(): Promise<void> {
        await this.detectHdr();
    }

    enable(): void {
        this._enabled = true;
    }

    disable(): void {
        this._enabled = false;
    }

    get enabled(): boolean {
        return this._enabled;
    }

    destroy(): void {
        if (this.loadedmetadataHandler) {
            this.player.removeEventListener('loadedmetadata', this.loadedmetadataHandler);
        }
    }
}

